CREATE TABLE IF NOT EXISTS v28_test_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),suite VARCHAR(120) NOT NULL,status VARCHAR(20) NOT NULL,started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),finished_at TIMESTAMPTZ,details JSONB,error_message TEXT);
CREATE TABLE IF NOT EXISTS student_enrollment_history_v28 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,academic_year_id UUID NOT NULL REFERENCES academic_years(id),class_id UUID REFERENCES classes(id),section_id UUID REFERENCES sections(id),status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',joined_on DATE NOT NULL DEFAULT CURRENT_DATE,left_on DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(student_id,academic_year_id));
CREATE INDEX IF NOT EXISTS idx_student_enrollment_history_v28 ON student_enrollment_history_v28(student_id,academic_year_id);
CREATE TABLE IF NOT EXISTS notification_delivery_attempts_v28 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),notification_id UUID,channel VARCHAR(30) NOT NULL,recipient VARCHAR(255) NOT NULL,provider VARCHAR(80),status VARCHAR(30) NOT NULL,provider_message_id VARCHAR(255),error_message TEXT,attempted_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_notification_delivery_v28 ON notification_delivery_attempts_v28(notification_id,attempted_at DESC);
CREATE TABLE IF NOT EXISTS e2e_workflow_runs_v28 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workflow VARCHAR(120) NOT NULL,status VARCHAR(20) NOT NULL,started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),finished_at TIMESTAMPTZ,details JSONB,error_message TEXT);
